// DNATechnologyContent.swift — chapter content and shared definitions.
import Foundation

enum DTTopic: String, CaseIterable, Identifiable, Hashable, Sendable {
    case recombinant, sequencing, pcr, editing, profiling, stemCells, cloning, medicine, ecology
    var id: String { rawValue }
    var article: DTArticle { DTArticle.all[self]! }
}
struct DTStage: Identifiable, Sendable {
    let id: String
    let title: String
    let heading: String
    let summary: String
    let bullets: [String]
    let terms: [String]
}
struct DTArticle: Sendable {
    let title: String
    let short: String
    let eyebrow: String
    let hex: UInt32
    let summary: String
    let stages: [DTStage]
    static let all: [DTTopic: DTArticle] = [
        .recombinant: .init(title: "Recombinant DNA", short: "Build", eyebrow: "COMBINE THE CODE",
            hex: 0xDECCE9, summary: "Join DNA from different sources, carry it into a host, and use the shared genetic code.", stages: [
                .init(id: "cdna", title: "Make cDNA", heading: "RNA becomes a DNA copy.",
                      summary: "Reverse transcriptase copies mature, spliced mRNA into complementary DNA.",
                      bullets: ["Bacteria do not splice eukaryotic introns. Using processed mRNA avoids transferring those introns.", "cDNA copies the processed RNA sequence, including any untranslated regions; exons are not all protein-coding."],
                      terms: ["reverseTranscriptase", "cdna", "geneticCode"]),
                .init(id: "join", title: "Cut & join", heading: "Matching ends. A sealed backbone.",
                      summary: "Restriction enzymes cut DNA; complementary sticky ends pair, and DNA ligase seals the join.",
                      bullets: ["Using compatible cuts on the insert and vector allows their sticky ends to base-pair.", "The joined DNA is recombinant DNA. Not every restriction enzyme produces sticky ends."],
                      terms: ["restrictionEnzyme", "stickyEnds", "ligase", "recombinantDNA"]),
                .init(id: "deliver", title: "Deliver", heading: "A vector carries the insert.",
                      summary: "A recombinant plasmid enters a host cell, where it can be copied and its gene expressed.",
                      bullets: ["Plasmids are small circular double-stranded DNA molecules separate from the main bacterial chromosome. Modified viruses can also be vectors.", "A transgenic organism carries introduced DNA in its genome. Inheritance depends on the cells receiving it; heritable animal changes must reach the germ line."],
                      terms: ["vector", "plasmid", "transformation", "transgenic"]),
                .init(id: "gmos", title: "GMOs", heading: "Different routes to new traits.",
                      summary: "Genetic engineering directly changes DNA; selective breeding selects inherited variation across generations.",
                      bullets: ["Engineered crops, including canola, corn, and soybeans, may resist herbicides or insects. Agrobacterium and a modified Ti plasmid can deliver genes to plants; Bt crops make insecticidal proteins from Bacillus thuringiensis.", "Animal examples include disease-model mice, fluorescent fish, fast-growing salmon, and livestock producing human therapeutic proteins, including proteins involved in blood clotting, in milk. DNA can be introduced using microinjection or viral vectors."],
                      terms: ["gmo", "selectiveBreeding", "agrobacterium", "bt"]),
            ]),
        .sequencing: .init(title: "DNA sequencing", short: "Read", eyebrow: "READ THE LETTERS",
            hex: 0xC8E7EF, summary: "Determine a DNA sequence, then connect individual reads to genes and whole genomes.", stages: [
                .init(id: "sanger", title: "Sanger", heading: "Stop a chain. Read its last base.",
                      summary: "DNA polymerase builds strands with ordinary nucleotides and occasional fluorescent chain terminators.",
                      bullets: ["A ddNTP stops extension because it lacks the 3′ hydroxyl needed to add the next nucleotide.", "Fragments are separated by size. Reading terminal colors from shortest to longest gives the newly synthesized strand, complementary to the template."],
                      terms: ["sanger", "ddntp", "electrophoresis"]),
                .init(id: "parallel", title: "Parallel reads", heading: "Many short reads, one larger picture.",
                      summary: "High-throughput methods read many DNA fragments in parallel, then software aligns or assembles the reads.",
                      bullets: ["The short-read approach in your notes uses overlapping fragments, often hundreds of bases long, on a surface or flow cell.", "Signals identify incorporated bases across many reactions. Fragment length and chemistry vary between sequencing platforms."],
                      terms: ["highThroughput", "genome"]),
                .init(id: "genome", title: "The genome", heading: "Noncoding does not mean useless.",
                      summary: "About 1.5% of the roughly 3.2-billion-base-pair human haploid genome encodes proteins.",
                      bullets: ["The remaining DNA includes RNA genes, regulatory sequences, introns, pseudogenes, and repeats.", "About 45% is recognizably derived from transposable elements in the conventional estimate. This is part of the noncoding fraction, not an extra 45% to add to it."],
                      terms: ["noncoding", "rnaGenes", "regulatory", "pseudogene", "transposon", "tandemRepeats"]),
            ]),
        .pcr: .init(title: "Polymerase chain reaction", short: "Copy", eyebrow: "AMPLIFY A TARGET",
            hex: 0xF7E49C, summary: "PCR repeatedly heats and cools a sample to make many copies of a selected DNA region.", stages: [
                .init(id: "heat", title: "Heat", heading: "Separate the strands.",
                      summary: "At about 95°C, the two DNA strands separate during denaturation.",
                      bullets: ["The target is the DNA region to be copied. Primers define the region amplified.", "Repeated cycles can yield millions of copies. The 2ⁿ counter is an idealized model; real reactions become less efficient."],
                      terms: ["pcr", "denaturation"]),
                .init(id: "prime", title: "Prime", heading: "Give polymerase a starting point.",
                      summary: "Cooling allows short synthetic DNA primers to base-pair with complementary sequences.",
                      bullets: ["Two primers bind opposite template strands, flanking the target region.", "Primers supply free 3′ ends. The polymerase adds nucleotides to those ends rather than starting a strand from scratch."],
                      terms: ["primer", "annealing"]),
                .init(id: "extend", title: "Extend", heading: "Build the complementary DNA.",
                      summary: "Heat-tolerant Taq polymerase extends the primers to synthesize new strands.",
                      bullets: ["Taq comes from Thermus aquaticus, a bacterium associated with hot springs. Extension synthesizes DNA in the 5′ → 3′ direction.", "PCR supports forensics and ancestry research. Reverse-transcription PCR first converts RNA to cDNA, as in many COVID-19 tests. Stray DNA can contaminate a reaction."],
                      terms: ["taq", "extension", "rtpcr", "contamination"]),
            ]),
        .editing: .init(title: "CRISPR-Cas9", short: "Edit", eyebrow: "TARGET, CUT, REPAIR",
            hex: 0xF3C9B5, summary: "A guide RNA helps Cas9 find DNA. The cell’s repair response determines the resulting change.", stages: [
                .init(id: "guide", title: "Guide", heading: "Match the target.",
                      summary: "Guide RNA contains a sequence complementary to the DNA target.",
                      bullets: ["The guide associates with Cas9 and helps position it at a matching sequence.", "Cas9 also requires an appropriate nearby PAM sequence. A guide alone does not guarantee perfectly specific editing."],
                      terms: ["guideRNA", "cas9", "pam"]),
                .init(id: "cut", title: "Cut", heading: "Make a targeted break.",
                      summary: "Cas9 cuts both DNA strands at the targeted location.",
                      bullets: ["The break itself is not a finished gene insertion or a guaranteed correction.", "Unintended changes can occur, including off-target cuts. Precision must be evaluated for each application."],
                      terms: ["crispr", "offTarget"]),
                .init(id: "repair", title: "Repair", heading: "The repair step makes the edit.",
                      summary: "Repair can disrupt a gene or, under suitable conditions, install a planned change.",
                      bullets: ["Different repair routes can produce small insertions or deletions, or use a supplied template to change a sequence.", "Newer approaches such as prime editing expand editing options. They do not eliminate all unintended effects."],
                      terms: ["repair", "primeEditing"]),
            ]),
        .profiling: .init(title: "DNA profiling", short: "Compare", eyebrow: "DETECT GENETIC DIFFERENCES",
            hex: 0xDECCE9, summary: "Compare variable DNA sites to investigate identity, relationships, and ancestry.", stages: [
                .init(id: "snp", title: "SNPs", heading: "One position. Different letters.",
                      summary: "A single-nucleotide polymorphism is a DNA position with a one-base difference among people.",
                      bullets: ["Millions of SNPs are known. Consumer tests often examine hundreds of thousands of selected sites rather than sequencing an entire genome.", "SNP patterns can inform ancestry estimates and probabilities for traits or disease risk, including lactose tolerance and variants linked to Parkinson’s or breast cancer. An association is not a certain prediction."],
                      terms: ["snp", "ancestry"]),
                .init(id: "str", title: "STRs", heading: "Count the repeated units.",
                      summary: "Short tandem repeat alleles differ in how many times a short DNA unit repeats.",
                      bullets: ["Real profiles compare many loci. U.S. CODIS uses 20 core STR loci; older panels used 13.", "Match rarity depends on the loci, profile, population, and assumptions. The chapter’s 1-in-250-trillion example is not a universal rate. DNA evidence has also helped exonerate wrongly convicted people."],
                      terms: ["str", "locus", "profileStatistics"]),
                .init(id: "mtdna", title: "mtDNA", heading: "Follow a maternal line.",
                      summary: "Human mitochondrial DNA is a small, roughly 16,500-base-pair circular genome.",
                      bullets: ["Its many copies can help recover information from degraded bones, teeth, or some hair samples.", "It is usually inherited from the mother. Maternal relatives, including full siblings, can share a sequence, so mtDNA alone may not distinguish them."],
                      terms: ["mtdna"]),
            ]),
        .stemCells: .init(title: "Stem cells", short: "Cells", eyebrow: "ONE START, DIFFERENT FATES",
            hex: 0xD0E5C2, summary: "Unspecialized cells can self-renew and differentiate. Their developmental potential differs.", stages: [
                .init(id: "embryonic", title: "Embryonic", heading: "Pluripotent: many body-cell types.",
                      summary: "Embryonic stem cells come from the inner cell mass of an early blastocyst, around five days after fertilization.",
                      bullets: ["Pluripotent cells can form the cell types of the body; they are not equivalent to a whole embryo.", "Embryo use raises ethical questions. Donor-derived cells can also face immune rejection."],
                      terms: ["stemCell", "pluripotent", "blastocyst"]),
                .init(id: "adult", title: "Adult", heading: "Multipotent: a narrower family.",
                      summary: "Adult tissue stem cells generate a more limited set of cell types for maintenance and repair.",
                      bullets: ["Examples include blood-forming stem cells in bone marrow and stem cells involved in skin renewal.", "Patient-derived cells can reduce immune mismatch, but compatibility and safety still depend on the cell product and its use."],
                      terms: ["multipotent", "adultStemCell"]),
                .init(id: "ipsc", title: "iPSCs", heading: "Reprogram a specialized cell.",
                      summary: "Laboratory reprogramming can return a somatic cell to a pluripotent state.",
                      bullets: ["Induced pluripotent stem cells can then be directed toward different specialized cell types.", "They avoid obtaining stem cells from an embryo. Patient matching can reduce immune mismatch, but does not guarantee rejection-free or safe treatment."],
                      terms: ["ipsc", "somatic", "differentiation"]),
            ]),
        .cloning: .init(title: "Cloning", short: "Clone", eyebrow: "SAME START, DIFFERENT GOALS",
            hex: 0xC8E7EF, summary: "Somatic cell nuclear transfer places a donor nucleus into an egg whose nucleus has been removed.", stages: [
                .init(id: "scnt", title: "SCNT", heading: "Transfer a diploid nucleus.",
                      summary: "Remove the egg nucleus, introduce a donor somatic nucleus, and stimulate development.",
                      bullets: ["The donor somatic nucleus is diploid (2n). The receiving unfertilized egg has its own nucleus removed.", "The developing embryo’s nuclear DNA follows the donor nucleus. Mitochondria and much of the cytoplasm come from the egg."],
                      terms: ["scnt", "somatic"]),
                .init(id: "reproductive", title: "Reproductive", heading: "Aim: an offspring.",
                      summary: "The SCNT embryo is transferred to a surrogate for gestation.",
                      bullets: ["Dolly the sheep, born in 1996, is a well-known example of cloning from an adult somatic cell.", "A clone is not an exact copy of appearance or life history: mitochondrial DNA, development, and environment can differ."],
                      terms: ["reproductiveClone"]),
                .init(id: "therapeutic", title: "Therapeutic", heading: "Aim: stem cells for research.",
                      summary: "The SCNT embryo is cultured to obtain pluripotent stem cells rather than implanted for an offspring.",
                      bullets: ["The goal is to study disease and potentially produce donor-matched cells or tissues.", "This is distinct from established routine production of replacement organs. Nuclear matching does not make every biological feature identical."],
                      terms: ["therapeuticClone"]),
            ]),
        .medicine: .init(title: "Tests, care & ethics", short: "Medicine", eyebrow: "USE THE INFORMATION",
            hex: 0xF3C9B5, summary: "DNA tools can detect variants, screen embryos, or change cell function—and raise ethical questions.", stages: [
                .init(id: "probe", title: "DNA probe", heading: "Find a complementary sequence.",
                      summary: "A tagged single-stranded DNA probe binds to a complementary target.",
                      bullets: ["The tag may be fluorescent or radioactive; binding produces a detectable signal.", "A probe can help distinguish a disease-associated allele, such as a cystic-fibrosis-associated variant."],
                      terms: ["dnaProbe"]),
                .init(id: "pgt", title: "Embryo testing", heading: "Screen before embryo transfer.",
                      summary: "Preimplantation genetic testing combines IVF with testing of a small embryo biopsy.",
                      bullets: ["The chapter describes removing a cell from an eight-cell embryo, amplifying DNA, and screening before transfer.", "Current practice commonly samples a few outer cells at the blastocyst stage, often day 5–7. The relevant test depends on what is being screened."],
                      terms: ["pgt", "ivf"]),
                .init(id: "testing", title: "Genetic tests", heading: "Detect an allele. Interpret its meaning.",
                      summary: "Testing blood or tissue can detect variants associated with inherited conditions or disease risk.",
                      bullets: ["BRCA1 variants can alter cancer risk; they do not mean that cancer is inevitable.", "Testing may involve fetal, childhood, or adult samples. PKU newborn screening commonly starts with biochemical testing; genetic testing can help confirm a cause."],
                      terms: ["geneticTest", "brca1", "pku"]),
                .init(id: "therapy", title: "Gene therapy", heading: "Change cells to treat disease.",
                      summary: "Gene addition can supply functional DNA to somatic cells, often using a modified viral vector.",
                      bullets: ["A research example is delivering functional CFTR DNA to airway cells. A vector carries the sequence into the target cells.", "Changing a treated person’s somatic cells does not automatically transmit the change to future children."],
                      terms: ["geneTherapy", "cftr", "vector"]),
                .init(id: "ethics", title: "Ethics", heading: "Powerful tools. Real choices.",
                      summary: "Questions include consent, privacy, access, embryo use, ecological effects, and genetic enhancement.",
                      bullets: ["Gene doping seeks athletic enhancement through genetic interventions, for example affecting muscle pathways or erythropoietin (EPO).", "Potential performance enhancement raises safety and fairness concerns. Therapeutic goals and enhancement goals should be distinguished."],
                      terms: ["geneDoping", "epo"]),
            ]),
        .ecology: .init(title: "Crops & gene flow", short: "Ecology", eyebrow: "FOLLOW THE EFFECT BEYOND THE CROP",
            hex: 0xD0E5C2, summary: "Introduced genes can move into relatives. A useful crop trait can also change weed fitness.", stages: [
                .init(id: "resistance", title: "Resistance", heading: "Keep a key pathway working.",
                      summary: "Glyphosate inhibits EPSPS, an enzyme in a pathway needed to make certain plant amino acids.",
                      bullets: ["Overproducing EPSPS is one way to increase resistance. Other resistant crops use EPSPS variants less sensitive to glyphosate.", "The chapter’s “booster gene” example concerns increased EPSPS expression under a strong promoter, not a universal mechanism for every resistant crop."],
                      terms: ["glyphosate", "epsps", "promoter"]),
                .init(id: "escape", title: "Gene flow", heading: "Pollen can move a transgene.",
                      summary: "Cross-pollination between compatible crops and weedy relatives can pass an introduced gene into hybrid offspring.",
                      bullets: ["Agrobacterium-mediated delivery and breeding are distinct steps from later pollen-mediated gene flow.", "A transgene that persists in relatives may affect how populations respond to their environment."],
                      terms: ["geneFlow", "transgenic"]),
                .init(id: "fitness", title: "Fitness", heading: "Benefits can persist without spraying.",
                      summary: "In the rice study, transgenic crop–weed hybrids had greater germination and seed production even without glyphosate.",
                      bullets: ["The comparison controlled genetic background and contrasted hybrids with and without the EPSPS transgene.", "The result shows a potential ecological risk: escaped genes can increase the reproductive success of some weeds. This does not mean every transgene has the same effect."],
                      terms: ["fitness", "geneFlow"]),
            ]),
    ]
}

struct DTTerm: Identifiable, Sendable {
    let id: String
    let name: String
    let definition: String
    let topic: DTTopic
    let asset: String
    static func find(_ id: String) -> DTTerm? { all.first { $0.id == id } }
    static let all: [DTTerm] = [
        .init(id: "geneticCode", name: "Shared genetic code", definition: "The nearly universal mapping between RNA codons and amino acids helps explain why transferred genes can be expressed across species. Host-compatible expression signals are also needed.", topic: .recombinant, asset: "recombinant"),
        .init(id: "gmo", name: "GMO", definition: "An organism whose genetic material has been changed using DNA technology. Herbicide-resistant and insect-resistant crops are common applications.", topic: .recombinant, asset: "recombinant"),
        .init(id: "selectiveBreeding", name: "Selective breeding", definition: "Choosing parents with desired inherited variation across generations, rather than directly editing their DNA.", topic: .recombinant, asset: "recombinant"),
        .init(id: "recombinantDNA", name: "Recombinant DNA", definition: "DNA joined from two or more sources. A source need not be a different species.", topic: .recombinant, asset: "recombinant"),
        .init(id: "transgenic", name: "Transgenic organism", definition: "An organism with introduced DNA incorporated into its genome. Stable inheritance depends on which cells carry the introduced DNA.", topic: .recombinant, asset: "recombinant"),
        .init(id: "reverseTranscriptase", name: "Reverse transcriptase", definition: "An enzyme that synthesizes DNA from an RNA template. It is used to make complementary DNA from processed mRNA.", topic: .recombinant, asset: "reverseTranscriptase"),
        .init(id: "cdna", name: "cDNA", definition: "Complementary DNA copied from RNA. cDNA made from mature eukaryotic mRNA lacks the removed introns but can retain untranslated exonic sequences.", topic: .recombinant, asset: "reverseTranscriptase"),
        .init(id: "vector", name: "Cloning vector", definition: "A DNA carrier that can maintain an insert in a host, often a self-replicating plasmid. Modified viruses are another delivery-vector example.", topic: .recombinant, asset: "recombinant"),
        .init(id: "plasmid", name: "Plasmid", definition: "A usually small circular double-stranded DNA molecule separate from a bacterial chromosome, widely used as a DNA vector.", topic: .recombinant, asset: "recombinant"),
        .init(id: "restrictionEnzyme", name: "Restriction enzyme", definition: "A protein that recognizes particular DNA sequences and cuts DNA. Many create sticky ends; others create blunt ends.", topic: .recombinant, asset: "recombinant"),
        .init(id: "stickyEnds", name: "Sticky ends", definition: "Short single-stranded DNA overhangs that can base-pair with complementary overhangs. DNA ligase is needed to seal the backbone.", topic: .recombinant, asset: "recombinant"),
        .init(id: "ligase", name: "DNA ligase", definition: "An enzyme that seals DNA backbone nicks by forming covalent phosphodiester bonds. Base pairing alone does not seal the backbone.", topic: .recombinant, asset: "recombinant"),
        .init(id: "transformation", name: "Transformation", definition: "Uptake of external DNA by a cell, such as a bacterium receiving a recombinant plasmid.", topic: .recombinant, asset: "recombinant"),
        .init(id: "agrobacterium", name: "Agrobacterium & Ti plasmid", definition: "Agrobacterium tumefaciens naturally transfers T-DNA into plant cells. Engineered Ti-plasmid systems replace harmful cargo with useful DNA.", topic: .recombinant, asset: "ecology"),
        .init(id: "bt", name: "Bt crops", definition: "Plants engineered to produce insecticidal proteins from Bacillus thuringiensis. Their intended trait differs from herbicide resistance.", topic: .recombinant, asset: "ecology"),
        .init(id: "sanger", name: "Sanger sequencing", definition: "Chain-termination sequencing: polymerase incorporates ordinary nucleotides and occasional labeled ddNTPs, producing fragments whose terminal bases reveal the sequence.", topic: .sequencing, asset: "sequencing"),
        .init(id: "ddntp", name: "ddNTP", definition: "A chain-terminating nucleotide lacking the 3′ hydroxyl needed for continued DNA synthesis. Fluorescent labels identify the terminal base.", topic: .sequencing, asset: "sequencing"),
        .init(id: "electrophoresis", name: "Electrophoresis", definition: "An electric field separates charged molecules. In Sanger sequencing, DNA fragments are resolved by size before their terminal colors are read.", topic: .sequencing, asset: "profiling"),
        .init(id: "highThroughput", name: "High-throughput sequencing", definition: "Methods that sequence many DNA molecules in parallel. The chapter’s overlapping short-fragment approach is one family of methods, not every platform.", topic: .sequencing, asset: "sequencing"),
        .init(id: "genome", name: "Genome", definition: "The full collection of an organism’s genetic material. One human haploid nuclear genome contains roughly 3.2 billion base pairs.", topic: .sequencing, asset: "sequencing"),
        .init(id: "noncoding", name: "Noncoding DNA", definition: "DNA outside protein-coding sequences. It includes RNA genes, regulatory elements, introns, pseudogenes, and repetitive DNA; it is not all functionless.", topic: .sequencing, asset: "sequencing"),
        .init(id: "rnaGenes", name: "RNA genes", definition: "Genes whose useful products are RNAs rather than proteins, including rRNA, tRNA, and microRNA.", topic: .sequencing, asset: "sequencing"),
        .init(id: "regulatory", name: "Regulatory DNA", definition: "Sequences such as promoters and enhancers that help control when and how strongly genes are expressed.", topic: .sequencing, asset: "sequencing"),
        .init(id: "pseudogene", name: "Pseudogene", definition: "A sequence resembling a functional gene that has lost its original protein-coding ability; some pseudogenes can still have regulatory roles.", topic: .sequencing, asset: "sequencing"),
        .init(id: "transposon", name: "Transposable elements", definition: "Mobile DNA and its descendants. A conventional estimate attributes about 45% of human DNA to recognizable transposable-element-derived sequences; most copies are no longer active.", topic: .sequencing, asset: "sequencing"),
        .init(id: "tandemRepeats", name: "Tandem repeats", definition: "DNA units repeated directly beside one another. STRs are short tandem repeats whose repeat counts can vary among individuals.", topic: .sequencing, asset: "profiling"),
        .init(id: "pcr", name: "PCR", definition: "Polymerase chain reaction amplifies a selected DNA region through repeated denaturation, primer annealing, and extension.", topic: .pcr, asset: "pcr"),
        .init(id: "denaturation", name: "Denaturation", definition: "The heating step that separates the two DNA template strands, typically around 95°C in PCR.", topic: .pcr, asset: "pcr"),
        .init(id: "primer", name: "Primer", definition: "A short synthetic DNA strand complementary to a template. It provides a free 3′ end for DNA polymerase to extend.", topic: .pcr, asset: "pcr"),
        .init(id: "annealing", name: "Annealing", definition: "Cooling allows complementary primers to base-pair with their template sequences.", topic: .pcr, asset: "pcr"),
        .init(id: "extension", name: "Extension", definition: "Polymerase adds complementary nucleotides to a primer’s 3′ end, synthesizing DNA in the 5′ → 3′ direction.", topic: .pcr, asset: "pcr"),
        .init(id: "taq", name: "Taq polymerase", definition: "A heat-tolerant DNA polymerase originally obtained from Thermus aquaticus; it functions across repeated PCR heat cycles.", topic: .pcr, asset: "pcr"),
        .init(id: "rtpcr", name: "Reverse-transcription PCR", definition: "RNA is first copied into cDNA by reverse transcriptase, then the cDNA is amplified. “RT” here means reverse transcription, not simply real-time detection.", topic: .pcr, asset: "reverseTranscriptase"),
        .init(id: "contamination", name: "Contamination", definition: "Stray DNA from other sources can be amplified along with the intended sample, misleading a highly sensitive PCR assay.", topic: .pcr, asset: "pcr"),
        .init(id: "crispr", name: "CRISPR-Cas9", definition: "An editing system using a guide RNA and the Cas9 protein to target and cut DNA. Cellular repair makes the resulting sequence change.", topic: .editing, asset: "editing"),
        .init(id: "guideRNA", name: "Guide RNA", definition: "RNA that associates with Cas9 and contains a sequence complementary to the intended DNA target.", topic: .editing, asset: "editing"),
        .init(id: "cas9", name: "Cas9", definition: "A guide-RNA-directed DNA-cutting protein. Conventional Cas9 editing creates a double-strand break.", topic: .editing, asset: "editing"),
        .init(id: "pam", name: "PAM", definition: "A short DNA motif adjacent to a potential target that a particular Cas9 protein must recognize before cutting.", topic: .editing, asset: "editing"),
        .init(id: "offTarget", name: "Off-target change", definition: "An unintended edit at a location other than the intended target. On-target changes can also differ from the desired result.", topic: .editing, asset: "editing"),
        .init(id: "repair", name: "DNA repair after editing", definition: "The cell’s response to a targeted break. Repair can disrupt a sequence or, in suitable contexts, use a supplied template to change it.", topic: .editing, asset: "editing"),
        .init(id: "primeEditing", name: "Prime editing", definition: "A newer editing approach combining a Cas9-derived nicking protein, reverse transcriptase, and a specialized guide RNA to install some targeted changes.", topic: .editing, asset: "editing"),
        .init(id: "snp", name: "SNP", definition: "A single-nucleotide polymorphism: a position where a one-base genetic variant occurs among individuals. Pronounced “snip.”", topic: .profiling, asset: "profiling"),
        .init(id: "ancestry", name: "Ancestry estimates", definition: "Statistical comparisons of genetic variants with reference populations. Results express likelihoods rather than a complete family history.", topic: .profiling, asset: "profiling"),
        .init(id: "str", name: "STR", definition: "A short tandem repeat: a short sequence, such as AGAT, repeated a variable number of times at a locus.", topic: .profiling, asset: "profiling"),
        .init(id: "locus", name: "Locus", definition: "A position in a genome. Profiling compares alleles at many loci rather than relying on one site.", topic: .profiling, asset: "profiling"),
        .init(id: "profileStatistics", name: "Profile statistics", definition: "A match probability depends on the genetic profile, comparison population, and assumptions. The chapter’s example rate is not a fixed property of all DNA matches.", topic: .profiling, asset: "profiling"),
        .init(id: "mtdna", name: "Mitochondrial DNA", definition: "A small circular genome in mitochondria. Multiple copies aid some degraded-sample analyses; usual maternal inheritance makes it useful for maternal-line comparisons.", topic: .profiling, asset: "profiling"),
        .init(id: "stemCell", name: "Stem cell", definition: "An unspecialized cell capable of self-renewal and differentiation into more specialized cells.", topic: .stemCells, asset: "stemCells"),
        .init(id: "pluripotent", name: "Pluripotent", definition: "Able to generate the cell types of the body. Embryonic stem cells and iPSCs are pluripotent; pluripotency is not the same as forming a whole embryo.", topic: .stemCells, asset: "stemCells"),
        .init(id: "blastocyst", name: "Blastocyst", definition: "An early embryo with an outer cell layer and an inner cell mass. Embryonic stem cells can be derived from the inner cell mass.", topic: .stemCells, asset: "stemCells"),
        .init(id: "multipotent", name: "Multipotent", definition: "Able to generate a more restricted range of related cell types, as with blood-forming adult stem cells.", topic: .stemCells, asset: "stemCells"),
        .init(id: "adultStemCell", name: "Adult stem cells", definition: "Tissue stem cells that support maintenance and repair, such as blood-forming cells in bone marrow and stem cells in skin.", topic: .stemCells, asset: "stemCells"),
        .init(id: "ipsc", name: "Induced pluripotent stem cells", definition: "iPSCs are somatic cells reprogrammed to pluripotency. They avoid embryo-derived starting material; patient matching does not guarantee safe or rejection-free treatment.", topic: .stemCells, asset: "stemCells"),
        .init(id: "somatic", name: "Somatic cell", definition: "A body cell other than a germ-line cell. A donor somatic nucleus is used in SCNT; somatic gene therapy targets body cells rather than creating an inherited germ-line change.", topic: .cloning, asset: "cloning"),
        .init(id: "differentiation", name: "Differentiation", definition: "Changes in gene expression and cell properties that produce a specialized cell type. Most specialized cells retain a broad genome despite using different genes.", topic: .stemCells, asset: "stemCells"),
        .init(id: "scnt", name: "SCNT", definition: "Somatic cell nuclear transfer places a donor body-cell nucleus into an egg whose nucleus has been removed, followed by stimulation of development.", topic: .cloning, asset: "cloning"),
        .init(id: "reproductiveClone", name: "Reproductive cloning", definition: "SCNT followed by embryo transfer to a surrogate with the aim of producing an offspring. Dolly the sheep was born in 1996.", topic: .cloning, asset: "cloning"),
        .init(id: "therapeuticClone", name: "Therapeutic cloning", definition: "SCNT with the aim of obtaining stem cells for research and potential regenerative applications, rather than producing an offspring.", topic: .cloning, asset: "cloning"),
        .init(id: "dnaProbe", name: "DNA probe", definition: "A labeled single-stranded DNA fragment that binds a complementary sequence. Fluorescent or radioactive tags make that binding detectable.", topic: .medicine, asset: "probe"),
        .init(id: "pgt", name: "Preimplantation genetic testing", definition: "PGT, formerly often called PGD, examines an IVF embryo biopsy before transfer. Modern practice commonly uses a few outer blastocyst cells rather than one cleavage-stage cell.", topic: .medicine, asset: "medicine"),
        .init(id: "ivf", name: "IVF", definition: "In vitro fertilization: fertilization outside the body, with embryos subsequently available for transfer or, when indicated, preimplantation testing.", topic: .medicine, asset: "medicine"),
        .init(id: "geneticTest", name: "Genetic testing", definition: "Analysis of DNA or other genetic information to investigate a variant, condition, or risk. Interpreting a result requires context; a risk allele is not a certain outcome.", topic: .medicine, asset: "medicine"),
        .init(id: "brca1", name: "BRCA1", definition: "A gene involved in DNA repair. Certain inherited variants raise the risk of some cancers, including breast cancer; risk is not the same as a diagnosis.", topic: .medicine, asset: "medicine"),
        .init(id: "pku", name: "PKU", definition: "Phenylketonuria is an inherited disorder affecting phenylalanine metabolism. Newborn screening often measures biochemical markers; DNA testing can identify an underlying cause.", topic: .medicine, asset: "medicine"),
        .init(id: "geneTherapy", name: "Gene therapy", definition: "A treatment strategy that changes genetic material or its use in cells. Gene addition may provide functional DNA using a modified vector.", topic: .medicine, asset: "medicine"),
        .init(id: "cftr", name: "CFTR", definition: "A gene encoding an ion channel. Delivering functional CFTR to airway cells is a gene-addition research example for cystic fibrosis.", topic: .medicine, asset: "medicine"),
        .init(id: "geneDoping", name: "Gene doping", definition: "Use of genetic or cellular interventions for athletic enhancement rather than treatment, raising safety and fairness concerns.", topic: .medicine, asset: "medicine"),
        .init(id: "epo", name: "Erythropoietin (EPO)", definition: "A hormone involved in red blood cell production. Altering EPO pathways is an example discussed in relation to gene doping.", topic: .medicine, asset: "medicine"),
        .init(id: "glyphosate", name: "Glyphosate", definition: "A herbicide that inhibits EPSPS in a pathway used to synthesize certain amino acids in plants.", topic: .ecology, asset: "ecology"),
        .init(id: "epsps", name: "EPSPS", definition: "5-enolpyruvylshikimate-3-phosphate synthase, an enzyme targeted by glyphosate. Increased expression was the mechanism tested in the rice example.", topic: .ecology, asset: "ecology"),
        .init(id: "promoter", name: "Promoter", definition: "A DNA regulatory region involved in starting transcription. A strong promoter can increase expression of an introduced or modified gene.", topic: .ecology, asset: "ecology"),
        .init(id: "geneFlow", name: "Gene flow", definition: "Movement of genetic variants between populations through reproduction, including crop–weed hybridization when the plants are compatible.", topic: .ecology, asset: "ecology"),
        .init(id: "fitness", name: "Evolutionary fitness", definition: "Reproductive success in a particular environment. Higher germination and seed production can increase the contribution of a genotype to later generations.", topic: .ecology, asset: "ecology"),
    ]
}
